    for row in tws.iter_rows():
        for cell in row:
            fc = fws.cell(row=cell.row, column=cell.column)
            # Compare key style attributes
            if (cell.font.b, cell.font.i, cell.font.name, cell.font.sz) != (fc.font.b, fc.font.i, fc.font.name, fc.font.sz):
                diffs.append((wsname, cell.coordinate, 'font'))
            if cell.number_format != fc.number_format:
                diffs.append((wsname, cell.coordinate, 'number_format'))
            if cell.fill.patternType != fc.fill.patternType or cell.fill.fgColor.rgb != fc.fill.fgColor.rgb:
                diffs.append((wsname, cell.coordinate, 'fill'))
            # borders
            for side in ['left','right','top','bottom']:
                b1 = getattr(cell.border, side); b2 = getattr(fc.border, side)
                if (b1.style, b1.color.rgb if b1.color else None) != (b2.style, b2.color.rgb if b2.color else None):
                    diffs.append((wsname, cell.coordinate, 'border_'+side))
